package com.template.auth.academic;
import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.util.zip.*;
import java.nio.charset.StandardCharsets;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.core.io.FileSystemResource;
import org.springframework.http.*;
import jakarta.servlet.http.HttpServletResponse;
import static com.template.auth.academic.AcademicDb.*;

@RestController @RequestMapping("/api/proyectos")
public class ProjectController {
    private final AcademicDb a; private final StorageService storage;
    public ProjectController(AcademicDb a,StorageService storage){this.a=a;this.storage=storage;}
    record Project(String title,String description,String career,String course,String kind,String members,String tags,String links,String requirements){}
    private void validate(Project p){str(p.title(),200,true);str(p.description(),8000,true);str(p.career(),150,true);str(p.course(),150,true);str(p.kind(),80,true);str(p.members(),1000,false);str(p.tags(),500,false);str(p.requirements(),2000,false);for(String l:str(p.links(),12000,false).split("\\R")){if(!l.isBlank())https(l.strip());}}
    private static final String BASE="select p.*,u.nombre||' '||u.apellido as author from academic_project p join usuario u on u.id=p.owner_id";
    private Map<String,Object> decorate(Map<String,Object> p,long me){long id=((Number)p.get("id")).longValue();p.put("mine",((Number)p.get("owner_id")).longValue()==me);p.put("files",a.db.queryForList("select id,name,bytes,is_main,is_cover from academic_file where project_id=? order by is_main desc,id",id));return p;}
    private Map<String,Object> detail(long id,long me){return decorate(a.one(BASE+" where p.id=?",id),me);}
    private void own(long id,long me){a.one("select id from academic_project where id=? and owner_id=? for update",id,me);}
    @GetMapping public Object list(Authentication auth,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String carrera,@RequestParam(defaultValue="") String curso,@RequestParam(required=false) Long autor,@RequestParam(defaultValue="false") boolean mine,@RequestParam(defaultValue="0") int page){long me=a.user(auth);if(page<0||page>100000)throw bad("Página inválida");StringBuilder sql=new StringBuilder(BASE+" where 1=1");List<Object> args=new ArrayList<>();if(mine||autor!=null){sql.append(" and p.owner_id=?");args.add(mine?me:autor);}if(!q.isBlank()){sql.append(" and (p.title||' '||p.description||' '||p.tags||' '||p.course||' '||p.career||' '||u.nombre||' '||u.apellido) ilike ?");args.add("%"+str(q,200,true)+"%");}if(!carrera.isBlank()){sql.append(" and p.career=?");args.add(carrera);}if(!curso.isBlank()){sql.append(" and p.course=?");args.add(curso);}sql.append(" order by p.created desc,p.id desc limit 25 offset ?");args.add(page*24);var rows=a.db.queryForList(sql.toString(),args.toArray());return Map.of("items",rows.stream().limit(24).map(p->decorate(p,me)).toList(),"hasNext",rows.size()>24);}
    @GetMapping("/filtros") public Object filters(){return a.db.queryForList("select distinct career,course from academic_project order by career,course");}
    @GetMapping("/{id}") public Object get(Authentication auth,@PathVariable long id){return detail(id,a.user(auth));}
    @PostMapping @Transactional public Object create(Authentication auth,@RequestBody Project p){validate(p);long me=a.user(auth);long id=((Number)a.one("insert into academic_project(owner_id,title,description,career,course,kind,members,tags,links,requirements) values(?,?,?,?,?,?,?,?,?,?) returning id",me,p.title().strip(),p.description().strip(),p.career().strip(),p.course().strip(),p.kind().strip(),str(p.members(),1000,false),str(p.tags(),500,false),str(p.links(),12000,false),str(p.requirements(),2000,false)).get("id")).longValue();return detail(id,me);}
    @PutMapping("/{id}") @Transactional public Object update(Authentication auth,@PathVariable long id,@RequestBody Project p){validate(p);long me=a.user(auth);own(id,me);a.db.update("update academic_project set title=?,description=?,career=?,course=?,kind=?,members=?,tags=?,links=?,requirements=? where id=?",p.title().strip(),p.description().strip(),p.career().strip(),p.course().strip(),p.kind().strip(),str(p.members(),1000,false),str(p.tags(),500,false),str(p.links(),12000,false),str(p.requirements(),2000,false),id);return detail(id,me);}
    @DeleteMapping("/{id}") @Transactional public void delete(Authentication auth,@PathVariable long id){own(id,a.user(auth));for(var f:a.db.queryForList("select storage_key from academic_file where project_id=?",id))storage.deleteAfterCommit((String)f.get("storage_key"));a.db.update("delete from academic_project where id=?",id);}
    private long total(long id){return a.db.queryForObject("select coalesce(sum(bytes),0) from academic_file where project_id=?",Long.class,id);}
    private void checkCover(MultipartFile f){if(!Set.of("png","jpg","jpeg","webp").contains(StorageService.extension(StorageService.name(f))))throw bad("La portada debe ser PNG, JPG o WEBP");}
    @PostMapping("/{id}/archivos") @Transactional(rollbackFor=Exception.class) public Object upload(Authentication auth,@PathVariable long id,@RequestParam MultipartFile file,@RequestParam(defaultValue="false") boolean cover) throws IOException {long me=a.user(auth);own(id,me);String name=StorageService.name(file);if(cover)checkCover(file);if(total(id)+file.getSize()>StorageService.MAX_PROJECT)throw bad("Máximo 500 MB por proyecto");if(a.db.queryForObject("select count(*) from academic_file where project_id=?",Long.class,id)>=50)throw bad("Máximo 50 archivos");if(cover){for(var f:a.db.queryForList("delete from academic_file where project_id=? and is_cover returning storage_key",id))storage.deleteAfterCommit((String)f.get("storage_key"));}boolean main=!cover&&a.db.queryForObject("select count(*) from academic_file where project_id=? and is_main",Long.class,id)==0;String key=storage.save(file);a.db.update("insert into academic_file(project_id,name,storage_key,bytes,is_main,is_cover) values(?,?,?,?,?,?)",id,name,key,file.getSize(),main,cover);return detail(id,me);}
    @PutMapping("/{id}/archivos/{fid}") @Transactional(rollbackFor=Exception.class) public Object replace(Authentication auth,@PathVariable long id,@PathVariable long fid,@RequestParam MultipartFile file)throws IOException{long me=a.user(auth);own(id,me);var old=a.one("select * from academic_file where project_id=? and id=?",id,fid);String name=StorageService.name(file);if(Boolean.TRUE.equals(old.get("is_cover")))checkCover(file);if(total(id)-((Number)old.get("bytes")).longValue()+file.getSize()>StorageService.MAX_PROJECT)throw bad("Máximo 500 MB por proyecto");String key=storage.save(file);a.db.update("update academic_file set name=?,storage_key=?,bytes=? where id=?",name,key,file.getSize(),fid);storage.deleteAfterCommit((String)old.get("storage_key"));return detail(id,me);}
    @DeleteMapping("/{id}/archivos/{fid}") @Transactional public Object deleteFile(Authentication auth,@PathVariable long id,@PathVariable long fid){long me=a.user(auth);own(id,me);var f=a.one("delete from academic_file where id=? and project_id=? returning *",fid,id);storage.deleteAfterCommit((String)f.get("storage_key"));if(Boolean.TRUE.equals(f.get("is_main")))a.db.update("update academic_file set is_main=true where id=(select min(id) from academic_file where project_id=? and not is_cover)",id);return detail(id,me);}
    @PutMapping("/{id}/archivo-principal/{fid}") @Transactional public Object main(Authentication auth,@PathVariable long id,@PathVariable long fid){long me=a.user(auth);own(id,me);a.one("select id from academic_file where id=? and project_id=? and not is_cover",fid,id);a.db.update("update academic_file set is_main=false where project_id=? and is_main",id);a.db.update("update academic_file set is_main=true where id=?",fid);return detail(id,me);}
    @GetMapping("/{id}/archivos/{fid}/descargar") public ResponseEntity<FileSystemResource> download(Authentication auth,@PathVariable long id,@PathVariable long fid){a.user(auth);var f=a.one("select * from academic_file where project_id=? and id=?",id,fid);var resource=new FileSystemResource(storage.path((String)f.get("storage_key")));if(!resource.exists())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Archivo no disponible");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename((String)f.get("name"),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").contentType(MediaType.APPLICATION_OCTET_STREAM).contentLength(((Number)f.get("bytes")).longValue()).body(resource);}
    @GetMapping("/{id}/descargar-zip") public void zip(Authentication auth,@PathVariable long id,HttpServletResponse response) throws IOException {a.user(auth);a.one("select id from academic_project where id=?",id);var files=a.db.queryForList("select * from academic_file where project_id=? and not is_cover order by id",id);if(files.isEmpty())throw bad("No hay archivos");for(var f:files)if(!Files.isRegularFile(storage.path((String)f.get("storage_key"))))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Archivo no disponible");response.setHeader(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=proyecto-"+id+".zip");response.setContentType("application/zip");response.setHeader("X-Content-Type-Options","nosniff");try(ZipOutputStream z=new ZipOutputStream(response.getOutputStream())){Set<String> used=new HashSet<>();for(var f:files){String name=(String)f.get("name");if(!used.add(name.toLowerCase(Locale.ROOT))){name=f.get("id")+"-"+name;while(!used.add(name.toLowerCase(Locale.ROOT)))name="_"+name;}z.putNextEntry(new ZipEntry(name));Files.copy(storage.path((String)f.get("storage_key")),z);z.closeEntry();}}}
    @GetMapping("/autor/{id}") public Object author(Authentication auth,@PathVariable long id){a.user(auth);return a.one("select id,nombre,apellido,carrera,biografia,ciclo from usuario where id=? and email_verificado=true",id);}
}
